import { Debugger, createDebugSession, type DebugMeta } from "march/ui"

// roket geri sayımı: dört satırlık bir program, 3. satırda kesme noktası; Başlat'a bas, Devam ile her turda n azalır
const SOURCE = `let n = 3
while (n > 0) {
  n--
}
console.log("kalkış!")`
const META: DebugMeta = { file: "roket.js", module: ["n"], fns: [], steps: [[1, 1, -1, "", [], []], [3, 3, -1, "", [], []], [5, 1, -1, "", [], []]] }
type Hooks = { s(f: number, s: number, g: () => (() => unknown)[]): void }

// programın hata ayıklayıcı çağrıları yazılmış hâli (derleyicinin instrument.js'i bunu kendisi yazar)
function run() {
  const d = (globalThis as unknown as { __marchDebug: Hooks }).__marchDebug
  d.s(0, 0, () => [() => n]); let n = 3
  while (n > 0) { d.s(0, 1, () => [() => n]); n-- }
  d.s(0, 2, () => [() => n]); console.log("kalkış!")
}

export function RocketCountdown() {
  const session = createDebugSession({ evaluate: async (expr, scope) => scope[expr] })
  session.setBreakpoint("roket.js", 3)
  session.addWatch("n")
  return <div sx={{ flex: "col", gap: 2 }}>
    <pre sx={{ p: 2, radius: 2, text: "sm" }}>{SOURCE}</pre>
    <Debugger session={session} sections={["watch", "output"]} timeline={false} options={false} onStart={() => { session.begin([META]); run() }} />
  </div>
}

import { Debugger, CodeEditor, createDebugSession, type DebugMeta } from "march/ui"

// indirim kodu neden işlemedi? Satır numarasına tıkla (kesme noktası), Başlat'a bas, adım adım rate'i izle
const FILE = "sepet.js"
const SOURCE = `function discount(price, code) {
  let rate = 0
  if (code === "HADI10") rate = 0.1
  return price * (1 - rate)
}
const final = discount(200, "hadi10")
console.log("ödenecek", final)`
const META: DebugMeta = { file: FILE, module: ["discount", "final"], fns: [["discount", 1]], steps: [
  [6, 1, -1, "", [], []], [2, 3, 0, "", ["rate", "price", "code"], []], [3, 3, 0, "", ["rate", "price", "code"], []],
  [4, 3, 0, "", ["rate", "price", "code"], []], [7, 1, -1, "", [], []],
] }
type Hooks = { s(f: number, s: number, g: () => (() => unknown)[]): void; e(f: number, n: number): number; x(at: number): void; t(e: unknown, at: number): unknown }

// programın hata ayıklayıcı çağrıları yazılmış hâli (derleyicinin instrument.js'i bunu kendisi yazar)
function run() {
  const d = (globalThis as unknown as { __marchDebug: Hooks }).__marchDebug
  function discount(price: number, code: string) {
    const f = d.e(0, 0)
    try {
      d.s(0, 1, () => [() => rate, () => price, () => code, () => discount, () => final]); let rate = 0
      d.s(0, 2, () => [() => rate, () => price, () => code, () => discount, () => final]); if (code === "HADI10") rate = 0.1
      d.s(0, 3, () => [() => rate, () => price, () => code, () => discount, () => final]); return price * (1 - rate)
    } catch (e) { throw d.t(e, f) } finally { d.x(f) }
  }
  d.s(0, 0, () => [() => discount, () => final]); const final = discount(200, "hadi10")
  d.s(0, 4, () => [() => discount, () => final]); console.log("ödenecek", final)
}

export function DiscountDebug() {
  const session = createDebugSession({ evaluate: async (expr, scope) => scope[expr] })
  session.setBreakpoint(FILE, 4)
  session.addWatch("rate")
  session.addWatch("code")
  return <div sx={{ flex: "col", gap: 2 }}>
    <CodeEditor lineNumbers readonly value={SOURCE} label={FILE} copy={false}
      lineMarks={() => session.breakpoints().map((b) => ({ line: b.line, kind: b.enabled ? "breakpoint" : "off" }))}
      activeLine={() => session.litLine(FILE)} onGutter={(line: number) => session.toggleBreakpoint(FILE, line)} />
    <Debugger session={session} depth={1} onStart={() => { session.begin([META]); run() }} />
  </div>
}

import { Debugger, Toggle, createDebugSession, type DebugMeta, type DebuggerSection } from "march/ui"
import { sparkles, star } from "march/icons"

// Debugger'ın bütün özellikleri: oturum, başlat / bitir, satıra git (onReveal), bölümler ve dizilişleri, çıktı satırı,
// başta açık bölümler, zaman çizelgesi, anahtarlar, kendi ikonların ve metinlerin, açık derinlik, sınıf
const META: DebugMeta = { file: "toplam.js", module: ["sum", "list"], fns: [], steps: [[1, 1, -1, "", [], []], [3, 3, -1, "", [], []], [5, 1, -1, "", [], []]] }
type Hooks = { s(f: number, s: number, g: () => (() => unknown)[]): void }
function run() {
  const d = (globalThis as unknown as { __marchDebug: Hooks }).__marchDebug
  d.s(0, 0, () => [() => sum, () => list]); let sum = 0; const list = [{ n: 2 }, { n: 5 }]
  for (const it of list) { d.s(0, 1, () => [() => sum, () => list]); sum += it.n }
  d.s(0, 2, () => [() => sum, () => list]); console.log("toplam", sum)
}
const ALL: DebuggerSection[] = ["watch", "scope", "stack", "breakpoints", "output"]

export function DebuggerLab() {
  const session = createDebugSession({ evaluate: async (expr, scope) => scope[expr], maxSteps: 500 })
  session.setBreakpoint("toplam.js", 3)
  session.addWatch("sum")
  let $runs = 0
  let $stopped = 0
  let $where = "—"
  let $full = true
  return <div sx={{ flex: "col", gap: 2 }}>
    <div sx={{ flex: ["row", "wrap"], gap: 3, text: "sm" }}>
      <span>Koşu: {$runs}</span><span>Bitirme: {$stopped}</span><span>Git: {$where}</span>
      <Toggle label="Tam panel" bind:value={$full} />
    </div>
    <Debugger
      session={session}
      onStart={() => { $runs++; session.begin([META]); run() }}
      onStop={() => { $stopped++; session.end() }}
      onReveal={(file, line) => $where = `${file}:${line}`}
      sections={() => $full ? ALL : ["watch", "breakpoints"]}
      layout={[["watch", "scope"], "breakpoints", ["stack", "output"]]}
      outputLines={3}
      open={["watch", "scope", "breakpoints", "output"]}
      timeline={() => $full}
      options={() => $full}
      icons={{ start: sparkles, resume: star, back: false }}
      labels={{ title: "Toplam avı", start: "Koş", restart: "Yeniden koş", resume: "Sürdür", stop: "Bitir", breakpoint: "Durakta durdu", idle: "Beklemede" }}
      depth={1}
      class="lab-dbg"
    />
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { DebuggerLab } from "./DebuggerLab.tsx"

// DebuggerLab'in testleri: kaydedince Testler sekmesinde çalışır
test("başta beklemede; kendi metinleri ve başlığı görünür", () => {
  const s = renderTest(() => <DebuggerLab />)
  expect(s.sees("Beklemede")).toBe(true)
  expect(s.get(".lab-dbg")?.getAttribute("aria-label")).toBe("Toplam avı")
})

test("Koş: kesme noktasında durur, onStart sayılır", async () => {
  const s = renderTest(() => <DebuggerLab />)
  await s.click("Koş (F5)")
  await s.wait(() => s.sees("Durakta durdu"))
  expect(s.sees("Koşu: 1")).toBe(true)
  expect(s.find("Sürdür (F8)")?.hasAttribute("disabled")).toBe(false)
})

test("Bitir onStop'u çağırır ve oturum biter", async () => {
  const s = renderTest(() => <DebuggerLab />)
  await s.click("Koş (F5)")
  await s.wait(() => s.sees("Durakta durdu"))
  await s.click("Bitir (Shift+F5)")
  expect(s.sees("Bitirme: 1")).toBe(true)
  expect(s.sees("Beklemede")).toBe(true)
})

test("kesme noktasının satırına basınca onReveal dosyayı ve satırı verir", async () => {
  const s = renderTest(() => <DebuggerLab />)
  // (aynı adı taşıyan onay kutusu değil, yanındaki satır düğmesi)
  await s.click(s.get(".lab-dbg button.m-dbg-at")!)
  expect(s.sees("Git: toplam.js:3")).toBe(true)
})
